$(document).ready(function(){$(".gallery").mauGallery({columns:{xs:1,sm:2,md:3,lg:3,xl:3},lightBox:!0,lightboxId:"myAwesomeLightbox",showTags:!0,tagsPosition:"top"});const e=document.getElementById("carouselExampleIndicators"),t=document.querySelectorAll(".carousel-item");e.addEventListener("slid.bs.carousel",()=>{t.forEach(e=>e.setAttribute("tabindex","-1"));const s=e.querySelector(".carousel-item.active");s.setAttribute("tabindex","0")});const s=new bootstrap.Carousel(e),a=document.querySelector(".toggle");let r=s._isPaused;a.addEventListener("click",()=>{r=!r,r?(s.pause(),a.textContent="⯈",a.setAttribute("aria-label","Carrousel mis en pause"),a.setAttribute("aria-pressed","true")):(s.cycle(),a.textContent="I I",a.setAttribute("aria-label","Mettre le carrousel en pause"),a.setAttribute("aria-pressed","false"))})});